import{_ as n,l as s,o as e,c as i,v as o,p as l,x as r,d,i as c,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"摩尔定律的经济学","description":"","frontmatter":{"title":"摩尔定律的经济学","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/moore-law-economics.md","filePath":"cs/moore-law-economics.md","lastUpdated":1789023840000}'),A={name:"cs/moore-law-economics.md"};function p(m,a,h,_,C,P){const t=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=o('<h1 id="摩尔定律的经济学" tabindex="-1">摩尔定律的经济学 <a class="header-anchor" href="#摩尔定律的经济学" aria-label="Permalink to &quot;摩尔定律的经济学&quot;">​</a></h1><div class="epigraph"><p>摩尔说的是单位成本下晶体管数的指数增长；墙之后密度仍可能涨，但掩膜、EDA 与验证的费用把「同一笔钱买到的性能」换成另一条曲线。</p><footer>—— 据 Moore, Cramming More Components onto Integrated Circuits, Electronics 1965；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/dennard-power-wall">上一课</a>把电场缩放与功耗墙分开。Moore 1965 的观察是<strong>经济学</strong>：芯片上晶体管数目按规律涨，因为这样划算。缺口是：NRE（设计、掩膜、软件）与每片硅成本如何决定「还要不要做新 ASIC」，以及 FPGA/标准单元/HLS 在成本曲线上的位置。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>晶体管更小不一定更便宜：EUV 掩膜套数、设计规则复杂度、验证周期都涨。缺口不是再讲 \\(CV^2f\\)，而是：<strong>固定成本</strong>摊到多少颗、多长产品寿命。数字系统课在此收一口：算术单元与接口能做，不意味着每代都值得全定制。</p><p>FPGA 摊掉掩膜，用面积/功耗换上市时间。HLS 降 RTL 人月，不降 P&amp;R 许可证与 STA 角。多核复用同一设计摊 NRE，对照功耗墙的并行。</p><h3 id="摩尔定律不是性能定律" tabindex="-1">摩尔定律不是性能定律 <a class="header-anchor" href="#摩尔定律不是性能定律" aria-label="Permalink to &quot;摩尔定律不是性能定律&quot;">​</a></h3><p>原文与后来的 Intel 表述围绕密度与成本。性能还要过 Dennard、存储墙、互连。把「每 18 个月翻倍」直接写成频率翻倍，与上一课矛盾，也与 DRAM 延迟曲线矛盾——后一单元内存会看见。</p><p><span class="marginnote">Moore, <em>Electronics</em>, 1965。CA:AQA 讨论成本、良率与工艺。本课不引用虚构的咨询报告数字；定性曲线足够。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>成本粗分：NRE / 件数 + 晶圆+封装测试。良率随面积指数变差，大芯片贵。平台化：同一 SoC 多 SKU 关单元（暗硅的市场版）。接口标准（后课 DDR、PCIe）让 PHY IP 摊到全行业，降低每家的模拟设计费用。</p>',11)),(e(),l(E,null,{default:r(()=>[c(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20DENS%5B%22%E5%AF%86%E5%BA%A6%E4%BB%8D%E5%8F%AF%E5%A2%9E%22%5D%20--%3E%20COST%5B%22%E6%8E%A9%E8%86%9C%E4%B8%8E%20NRE%22%5D%0A%20%20COST%20--%3E%20CHOICE%5B%22ASIC%20vs%20FPGA%20vs%20%E4%B9%B0%20IP%22%5D%0A%20%20WALL%5B%22%E5%8A%9F%E8%80%97%E5%A2%99%22%5D%20--%3E%20CHOICE%0A%20%20CHOICE%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E9%AA%8C%E8%AF%81%E5%BF%85%E9%A1%BB%E5%88%97%E5%85%A5%20NRE%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>后课验证、DFT、BIST 都是 NRE 的一部分：少测会把成本赶到现场失效。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>本课序的 HDL 路径到此从「如何做」兼及「为何有时不做」。内存与 PCIe 单元假设多数设计者<strong>买 IP</strong>，自己做控制器调度与软件，而不是从晶体管画 DDR PHY。ISA 对照同理：授权与生态也是经济学。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不预测某代工艺的晶圆报价，不讨论出口管制。不把股市当文献。不进入光刻机产能。量化金融定价不是本栏。</p><p>后课默认：密度趋势与「更便宜的性能」已脱钩；验证与 IP 是成本一等公民。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Moore 原意是成本–密度；不是频率定律。</li><li>NRE 与掩膜把全定制门槛抬高；FPGA/IP 是回应。</li><li>下一课起把验证计入这条成本。</li><li>出处：Moore, <em>Electronics</em>, 1965；Hennessy and Patterson, CA:AQA。</li></ul>',8))])}const S=n(A,[["render",p]]);export{f as __pageData,S as default};
